// O(1) — Tiempo constante: siempre la misma cantidad de operaciones
int primerEnemigo = enemies[0];          // Acceso por índice: O(1)
bool existe = dict.ContainsKey("Boss");  // Lookup en Dictionary: O(1)

// O(n) — Tiempo lineal: crece proporcional al tamaño de la entrada
foreach (Enemy e in enemies)             // Un bucle sobre n enemigos: O(n)
    e.UpdateAI();

// O(n²) — Tiempo cuadrático: dos bucles anidados sobre la misma colección
for (int i = 0; i < enemies.Count; i++)
    for (int j = 0; j < enemies.Count; j++) // ← O(n²)
        CheckCollision(enemies[i], enemies[j]);

// O(log n) — Tiempo logarítmico: divide el problema a la mitad cada vez
// Ejemplo: búsqueda binaria en un array ordenado de waypoints
int mid = BinarySearch(sortedWaypoints, target); // O(log n)

